MODULE_SOURCE='from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom pathlib import Path\nfrom hashlib import sha256\nimport json\n\nfrom .opl_001_production_learning_foundation import connect,STATE_TABLE,LEDGER_TABLE,ensure_production_learning_schema\nfrom .opl_002_canonical_evidence_index import sync_evidence_index,find_pre_settlement_evidence_batch\n\nOPL_003_BUILD_ID="OPL-003"\nOPL_003_REVISION="OPL_003_OUTCOME_GROUNDED_PRODUCTION_LEARNING_CYCLE_V1"\n\n@dataclass(frozen=True)\nclass SettledOutcome:\n    ticker:str\n    result:str\n    settlement_ts:str\n    source_hash:str\n    raw:dict\n\n@dataclass(frozen=True)\nclass ProductionLearningCycleSummary:\n    settled_scanned:int\n    already_learned:int\n    evidence_matched:int\n    evidence_missing:int\n    admitted:int\n    applied:int\n    production_learned_total:int\n    evidence_coverage:float\n    learning_yield:float\n    state_hash:str\n\ndef _h(v):\n    return sha256(json.dumps(v,sort_keys=True,separators=(",",":"),default=str).encode()).hexdigest()\n\ndef normalize_settled_market(m):\n    m=dict(m);ticker=str(m.get("ticker") or "").strip().upper();result=str(m.get("result") or "").strip().lower()\n    ts=str(m.get("settlement_ts") or m.get("settled_ts") or m.get("settled_time") or "").strip()\n    if not ticker or result not in ("yes","no","scalar") or not ts:return None\n    return SettledOutcome(ticker,result,ts,_h(m),m)\n\ndef fetch_settled_pages(root=None,page_limit=10,page_size=1000):\n    from qseries_v2.oracle_adapters.kalshi.oad_021_credentials import load_kalshi_credentials\n    from qseries_v2.oracle_adapters.kalshi.oad_022_rest_transport import kalshi_rest_get\n    root=Path(root or Path.cwd()).resolve();c=load_kalshi_credentials(root=root)\n    cursor=None;out=[];seen=set()\n    for _ in range(int(page_limit)):\n        params={"limit":max(1,min(int(page_size),1000)),"status":"settled"}\n        if cursor:params["cursor"]=cursor\n        r=kalshi_rest_get(c,"/markets",params,15)\n        for raw in r.body.get("markets",()):\n            o=normalize_settled_market(raw)\n            if o and o.source_hash not in seen:\n                seen.add(o.source_hash);out.append(o)\n        cursor=r.body.get("cursor")\n        if not cursor:break\n    return tuple(sorted(out,key=lambda x:(x.settlement_ts,x.ticker),reverse=True))\n\ndef _genesis_ocl_state():\n    from qseries_v2.oracle_continuous_learner.ocl_027_incremental_state_runtime import genesis_incremental_state\n    return genesis_incremental_state()\n\ndef _load_ocl_state(raw):\n    from qseries_v2.oracle_continuous_learner.ocl_027_incremental_state_runtime import IncrementalLearnerState\n    if not raw:return _genesis_ocl_state()\n    return IncrementalLearnerState(**dict(raw))\n\ndef _build_runtime_input(sequence,outcome,evidence):\n    from qseries_v2.oracle_continuous_learner.ocl_003_outcome_observation import build_outcome_observation\n    from qseries_v2.oracle_continuous_learner.ocl_004_learning_event import assemble_learning_event\n    from qseries_v2.oracle_continuous_learner.ocl_026_continuous_intake_runtime import build_runtime_input\n    value=True if outcome.result=="yes" else False if outcome.result=="no" else outcome.raw.get("settlement_value")\n    oo=build_outcome_observation(outcome.ticker,"settlement",value,outcome.settlement_ts,"kalshi:"+outcome.ticker,outcome.source_hash)\n    lineage=sha256((evidence.evidence_hash+outcome.source_hash).encode()).hexdigest()\n    event=assemble_learning_event(outcome.ticker,evidence.evidence_hash,lineage,oo)\n    ri=build_runtime_input(int(sequence),"learning_event",event.event_id,event.event_hash,{\n        "subject_id":event.subject_id,"evidence_hash":event.evidence_hash,\n        "outcome_hash":event.outcome_hash,"lineage_hash":event.lineage_hash,\n        "outcome_type":event.outcome_type})\n    return ri,event.event_hash\n\ndef run_production_learning_cycle(root=None,settled_page_limit=20,evidence_limit=5,progress=print):\n    from qseries_v2.oracle_continuous_learner.ocl_026_continuous_intake_runtime import assemble_runtime_batch\n    from qseries_v2.oracle_continuous_learner.ocl_028_learning_cycle_orchestrator import run_learning_cycle\n\n    root=Path(root or Path.cwd()).resolve();ensure_production_learning_schema(root)\n    sync=sync_evidence_index(root,batch_size=5000,max_batches=10,backfill_if_empty=100000)\n    outcomes=fetch_settled_pages(root,page_limit=settled_page_limit,page_size=1000)\n\n    with connect(root) as conn:\n        with conn.cursor() as cur:\n            cur.execute(f"""SELECT legacy_outcomes_learned,production_outcomes_learned,cycles,\n              applied_through_sequence,ocl_state_json,last_settlement_ts,last_ticker,state_hash\n              FROM public.{STATE_TABLE} WHERE state_id=1 FOR UPDATE""")\n            st=cur.fetchone()\n            legacy,prod,cycles,through,raw_state,last_ts,last_ticker,state_hash=st\n            ocl=_load_ocl_state(raw_state)\n\n            dup=matched=missing=admitted=0;inputs=[];pending=[];seq=int(through)\n\n            cur.execute(f"SELECT settlement_hash,status FROM public.{LEDGER_TABLE} WHERE settlement_hash = ANY(%s)",\n                        ([o.source_hash for o in outcomes],))\n            existing={str(h):str(s) for h,s in cur.fetchall()}\n            unresolved=[o for o in outcomes if existing.get(o.source_hash)!="LEARNED"]\n            dup=len(outcomes)-len(unresolved)\n            evidence_map=find_pre_settlement_evidence_batch(\n                root,{o.ticker:o.settlement_ts for o in unresolved},evidence_limit\n            )\n\n            for o in unresolved:\n                evidence=evidence_map.get(o.ticker,())\n                if not evidence:\n                    missing+=1\n                    cur.execute(f"""INSERT INTO public.{LEDGER_TABLE}\n                      (settlement_hash,ticker,result,settlement_ts,status)\n                      VALUES(%s,%s,%s,%s,\'EVIDENCE_MISSING\')\n                      ON CONFLICT(settlement_hash) DO UPDATE SET\n                      status=\'EVIDENCE_MISSING\',updated_at=clock_timestamp()""",\n                      (o.source_hash,o.ticker,o.result,o.settlement_ts))\n                    continue\n\n                e=evidence[0];matched+=1;seq+=1\n                ri,event_hash=_build_runtime_input(seq,o,e)\n                inputs.append(ri);pending.append((o,e,event_hash));admitted+=1\n                cur.execute(f"""INSERT INTO public.{LEDGER_TABLE}\n                  (settlement_hash,ticker,result,settlement_ts,evidence_observation_id,\n                   evidence_hash,evidence_sequence_number,learning_event_hash,status)\n                  VALUES(%s,%s,%s,%s,%s,%s,%s,%s,\'ELIGIBLE\')\n                  ON CONFLICT(settlement_hash) DO UPDATE SET\n                  evidence_observation_id=EXCLUDED.evidence_observation_id,\n                  evidence_hash=EXCLUDED.evidence_hash,\n                  evidence_sequence_number=EXCLUDED.evidence_sequence_number,\n                  learning_event_hash=EXCLUDED.learning_event_hash,\n                  status=\'ELIGIBLE\',updated_at=clock_timestamp()""",\n                  (o.source_hash,o.ticker,o.result,o.settlement_ts,e.observation_id,e.evidence_hash,e.sequence_number,event_hash))\n                if admitted>=250:\n                    break\n\n            applied=0\n            if inputs:\n                batch=assemble_runtime_batch(tuple(inputs))\n                result,new_ocl=run_learning_cycle(int(cycles)+1,ocl,batch)\n                applied=len(inputs);prod=int(prod)+applied;cycles=int(cycles)+1\n                last=max((x[0] for x in pending),key=lambda x:(x.settlement_ts,x.ticker))\n                for o,e,event_hash in pending:\n                    cur.execute(f"""UPDATE public.{LEDGER_TABLE} SET status=\'LEARNED\',\n                      learned_at=clock_timestamp(),updated_at=clock_timestamp()\n                      WHERE settlement_hash=%s""",(o.source_hash,))\n                cur.execute(f"""UPDATE public.{STATE_TABLE} SET\n                    production_outcomes_learned=%s,cycles=%s,applied_through_sequence=%s,\n                    ocl_state_json=%s::jsonb,last_settlement_ts=%s,last_ticker=%s,state_hash=%s,\n                    updated_at=clock_timestamp() WHERE state_id=1""",\n                    (prod,cycles,int(new_ocl.applied_through_sequence),\n                     json.dumps(asdict(new_ocl),sort_keys=True),\n                     last.settlement_ts,last.ticker,new_ocl.state_hash))\n                state_hash=new_ocl.state_hash\n                progress(f"[OPL LEARN] applied={applied} production_total={prod} cycle={cycles} through_sequence={new_ocl.applied_through_sequence}")\n                progress(f"[OPL LEARN] state_hash={new_ocl.state_hash} cycle_hash={result.cycle_hash}")\n\n        conn.commit()\n\n    eligible=max(1,len(outcomes)-dup)\n    coverage=matched/eligible if eligible else 0.0\n    yield_=applied/matched if matched else 0.0\n    progress(f"[OPL METRICS] settled={len(outcomes)} duplicates={dup} evidence_matched={matched} evidence_missing={missing} admitted={admitted} applied={applied} evidence_coverage={coverage:.3f} learning_yield={yield_:.3f} indexed={sync[\'inserted\']}")\n    return ProductionLearningCycleSummary(len(outcomes),dup,matched,missing,admitted,applied,int(prod),coverage,yield_,str(state_hash or ""))\n\ndef verify_opl_003_outcome_grounded_production_learning_cycle(root=None):\n    x=normalize_settled_market({"ticker":"KXTEST","result":"yes","settlement_ts":"2026-08-18T00:00:00Z"})\n    return OPL_003_BUILD_ID=="OPL-003" and x is not None and x.result=="yes"\n';TEST_SOURCE='import unittest\nfrom qseries_v2.oracle_production_learning.opl_003_outcome_grounded_production_learning_cycle import *\nclass T(unittest.TestCase):\n    def test_normalize(self):\n        x=normalize_settled_market({"ticker":"KXTEST","result":"YES","settlement_ts":"t"})\n        self.assertEqual(x.ticker,"KXTEST");self.assertEqual(x.result,"yes")\n    def test_reject(self):self.assertIsNone(normalize_settled_market({"ticker":"KX","result":"","settlement_ts":"t"}))\nif __name__=="__main__":\n    print("="*88);print(" OPL-003 CERTIFICATION TEST");print(" OUTCOME-GROUNDED PRODUCTION LEARNING CYCLE");print("="*88)\n    r=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not r.wasSuccessful():raise SystemExit(1)\n    print("[PASS] Production settlement normalization certified")\n    print("[PASS] execution_authority=FALSE")\n    print("[DONE] OPL-003 CERTIFIED")\n'

def write_exact(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(text,encoding="utf-8",newline="\n")
    os.replace(tmp,path)

def restore(path,data):
    if data is None:
        if path.exists(): path.unlink()
    else:
        path.write_bytes(data)

def update_init(path,export):
    current=path.read_text(encoding="utf-8") if path.exists() else ""
    if export not in current.splitlines():
        write_exact(path,current.rstrip()+"\n"+export+"\n")

def main():
    print("="*88);print(" OPL-003 INSTALLER");print(" OUTCOME-GROUNDED PRODUCTION LEARNING CYCLE");print("="*88);print("[ROOT]",ROOT)
    sys.path.insert(0,str(ROOT));up=importlib.import_module("qseries_v2.oracle_production_learning.opl_002_canonical_evidence_index")
    if not up.verify_opl_002_canonical_evidence_index(ROOT):raise RuntimeError("OPL-002 verification failed")
    affected=(MOD,TEST,INIT);old={p:(p.read_bytes() if p.exists() else None) for p in affected}
    try:
        write_exact(MOD,MODULE_SOURCE);write_exact(TEST,TEST_SOURCE);update_init(INIT,"from .opl_003_outcome_grounded_production_learning_cycle import *")
        subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=True)
    except Exception:
        for p,b in old.items():restore(p,b)
        print("[ROLLBACK] OPL-003 failed; files restored");raise
    print("[PASS] Old OLR runtime not modified")
    print("[PASS] execution_authority=FALSE")
    print("[DONE] OPL-003 INSTALLATION COMPLETE")
if __name__=="__main__":main()
